package com.motionstudio.part2
import kotlin.math.*
object ImageEffects {
 data class Params(val brightness:Float=0f,val contrast:Float=1f,val exposure:Float=0f,val saturation:Float=1f,val hue:Float=0f,val gamma:Float=1f,val invert:Boolean=false,val grayscale:Boolean=false,val threshold:Float?=null,val posterize:Int?=null,val sharpen:Float=0f,val vignette:Float=0f,val noise:Float=0f,val grain:Float=0f,val pixelation:Int=1,val edge:Float=0f,val emboss:Float=0f,val rgbSplit:Float=0f,val channelMatrix:FloatArray?=null,val seed:Long=0L)
 fun apply(src:FrameBuffer,p:Params):FrameBuffer { require(p.gamma>0f&&p.saturation>=0f&&p.pixelation>0&&((p.posterize==null)||(p.posterize>=2))) ; val out=FrameBuffer(src.width,src.height); val rnd=DeterministicRng(p.seed); for(y in 0 until src.height)for(x in 0 until src.width){ val sx=(x/p.pixelation)*p.pixelation;val sy=(y/p.pixelation)*p.pixelation;var c=src.get(sx.coerceIn(0,src.width-1),sy.coerceIn(0,src.height-1)); var r=c.r*2f.pow(p.exposure)+p.brightness;var g=c.g*2f.pow(p.exposure)+p.brightness;var b=c.b*2f.pow(p.exposure)+p.brightness;val lum=.2126f*r+.7152f*g+.0722f*b;r=lum+(r-lum)*p.saturation;g=lum+(g-lum)*p.saturation;b=lum+(b-lum)*p.saturation;val angle=p.hue*PI.toFloat()/180f;val cs=cos(angle);val sn=sin(angle);val rr=(.213f+.787f*cs-.213f*sn)*r+(.715f-.715f*cs+.143f*sn)*g+(.072f-.072f*cs+.928f*sn)*b;val gg=(.213f-.213f*cs+.787f*sn)*r+(.715f+.285f*cs+.14f*sn)*g+(.072f-.072f*cs-.283f*sn)*b;val bb=(.213f-.213f*cs-.787f*sn)*r+(.715f-.715f*cs-.14f*sn)*g+(.072f+.928f*cs+.072f*sn)*b;r=rr;g=gg;b=bb; r=((r-.5f)*p.contrast+.5f).coerceIn(0f,1f);g=((g-.5f)*p.contrast+.5f).coerceIn(0f,1f);b=((b-.5f)*p.contrast+.5f).coerceIn(0f,1f);if(p.gamma!=1f){val inv=1f/p.gamma;r=r.pow(inv);g=g.pow(inv);b=b.pow(inv)};if(p.invert){r=1-r;g=1-g;b=1-b};if(p.grayscale){val q=.2126f*r+.7152f*g+.0722f*b;r=q;g=q;b=q};p.threshold?.let{val q=if((.2126f*r+.7152f*g+.0722f*b)>=it)1f else 0f;r=q;g=q;b=q};p.posterize?.let{val n=(it-1).toFloat();r=round(r*n)/n;g=round(g*n)/n;b=round(b*n)/n};val dx=x.toFloat()/src.width-.5f;val dy=y.toFloat()/src.height-.5f;val vig=(1f-p.vignette*(dx*dx+dy*dy)*4f).coerceAtLeast(0f);r*=vig;g*=vig;b*=vig;val n=(rnd.nextFloat()-.5f)*(p.noise+p.grain);r+=n;g+=n;b+=n;if(p.channelMatrix!=null){require(p.channelMatrix.size==9);val m=p.channelMatrix;r0@run { val nr=m[0]*r+m[1]*g+m[2]*b;val ng=m[3]*r+m[4]*g+m[5]*b;val nb=m[6]*r+m[7]*g+m[8]*b;r=nr;g=ng;b=nb }};out.set(x,y,Rgba(r,g,b,c.a))}; if(p.sharpen>0||p.edge!=0f||p.emboss!=0f) return kernelPost(out,p); return out }
 private fun kernelPost(src:FrameBuffer,p:Params):FrameBuffer{val o=src.copy();for(y in 1 until src.height-1)for(x in 1 until src.width-1){val c=src.get(x,y);val lum={xx:Int,yy:Int->src.get(xx,yy).r*.2126f+src.get(xx,yy).g*.7152f+src.get(xx,yy).b*.0722f};val l=lum(x-1,y)+lum(x+1,y)+lum(x,y-1)+lum(x,y+1)-4*lum(x,y);val e=abs(l);val v=(c.r+p.sharpen*l+p.edge*e+p.emboss*(lum(x+1,y+1)-lum(x-1,y-1))).coerceIn(0f,1f);o.set(x,y,Rgba(v,v,v,c.a))};return o }
 private class DeterministicRng(var s:Long){fun nextFloat():Float{s=(s*6364136223846793005L+1442695040888963407L);return ((s ushr 40) and 0xffffff).toFloat()/16777216f}}
}
